function chatBox(){var A=S.ai;if(!A)return "";var M=A.messages||[],busy=A.busy||CH.sending,own=!!A.own;
var head='<div class="tc-chd"><div class="tc-chn">'+aiMark()+'<div><b>'+esc(aiName())+'</b><small>'+(busy?'<span class="ok">Working…</span>':A.provider?esc(A.provider.note||'Your Claude, on this computer'):'Not set up')+'</small></div></div>'+
'<div class="tc-chr">'+(A.provider&&A.provider.tiers?'<label class="tc-chk" title="Fast answers most things. Smart thinks harder and costs twice as much.">'+svgSpark()+'<select onchange="setTier(this.value)"><option value="fast"'+(A.tier!=="smart"?" selected":"")+'>Fast · 2¢</option><option value="smart"'+(A.tier==="smart"?" selected":"")+'>Smart · 4¢</option></select></label>':'')+'<label class="tc-chk" title="Let the AI review your rules on a schedule">'+svgClock()+'<select onchange="setCheckin(this.value)">'+[[0,"Check-ins off"],[1,"Every hour"],[4,"Every 4 hours"],[12,"Every 12 hours"],[24,"Daily"]].map(function(o){return '<option value="'+o[0]+'"'+(A.checkin.every_hours===o[0]?" selected":"")+'>'+o[1]+'</option>'}).join("")+'</select></label>'+(M.length?'<button class="b g tc-chx'+(CH.confirmNew?" tc-warn":"")+'" onclick="newChat()" title="Start over. Your rules stay on.">'+(CH.confirmNew?'Clear chat?':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h4L19 9l-4-4L4 16z M14 6l4 4" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/></svg>New chat')+'</button>':'')+'</div></div>';
if(!A.provider)return '<div class="tc-chat">'+head+'<div class="tc-cempty"><b>Chat with your AI here</b><p>Install <b>Claude Code</b> on this computer and sign in once (run <code>claude</code> in Terminal). Then reopen this page. It uses your own Claude plan; the wallet never sees your Claude login.</p></div></div>';
var body=M.length?M.map(function(m,i){return chatMsg(m,i===M.length-1)}).join(""):'<div class="tc-cempty"><b>Ask '+esc(aiName())+' about your money</b><p>Say it in your own words. '+esc(aiName())+' checks prices and your balances, then sets up the swap or rule you describe. Nothing happens until you tap Approve or Turn on.</p>'+(tkClaude()?'<p class="tc-own">Rather use ChatGPT, Cursor, Gemini CLI or another AI app? <a href="#" onclick="openAI();return false">Connect it for free</a> and chat there instead.</p>':'')+'<div class="tc-cchips">'+CHIPS.map(function(c,i){return '<button class="tc-cchip" onclick="chatSend(CHIPS['+i+'])">'+esc(c)+'</button>'}).join("")+'</div></div>';
if(busy)body+='<div class="tc-cm tc-ai">'+aiAv()+'<div class="tc-cbw"><div class="tc-cb tc-ctyping"><i></i><i></i><i></i><span>'+(A.busy&&A.busy.note?esc(A.busy.note):A.busy&&A.busy.kind==="checkin"?"Checking in on your rules…":"Looking at prices and your wallet…")+'</span></div></div></div>';
var pw=!A.ready?'<div class="tc-cpw"><div class="sm">One time: your wallet password lets '+esc(aiName())+' read your balances. It’s saved on this computer, readable only by your account.</div><div class="tc-crow"><input id="chpw" type="password" placeholder="Wallet password" value="'+esc(CH.pw)+'" oninput="CH.pw=this.value"><button class="b" onclick="chatPw()">Save</button></div></div>':"";
var pics=ownImg()&&A.ready,att=pics?'<button class="attb" onclick="pickImg()" aria-label="Add a picture"'+(busy?" disabled":"")+'>'+svgI(OWI.img).replace("<svg",'<svg width="19" height="19"')+'</button><input type="file" id="chimg" accept="image/*" multiple hidden onchange="onImg(this.files);this.value=\'\'">':'',prev=pics&&OW.imgs.length?'<div class="attch">'+OW.imgs.map(function(x,i){return '<div class="th"><img src="'+x.thumb+'" alt="Picture to send"><button onclick="rmImg('+i+')" aria-label="Remove picture">×</button></div>'}).join("")+'</div>':'';
var inp=prev+'<div class="tc-cin">'+att+'<textarea id="chin" rows="1" placeholder="Message '+esc(aiName())+'…" oninput="CH.draft=this.value;grow(this)" onpaste="imgPaste(event)" onkeydown="if(event.key===\'Enter\'&&!event.shiftKey){event.preventDefault();chatSend()}"'+(A.ready?"":" disabled")+'>'+esc(CH.draft)+'</textarea><button class="b tc-csend" onclick="chatSend()"'+(busy||!A.ready?" disabled":"")+' aria-label="Send"><svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M5 12h13M13 6l6 6-6 6" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div>';
return '<div class="tc-chat'+(own?" v2":"")+'">'+(own?"":head)+'<div class="tc-cbody" id="cbody">'+body+'</div>'+(CH.err?'<div class="msg tc-err" style="margin:0 12px 10px">'+esc(CH.err)+'</div>':'')+pw+inp+'</div>'}
