function aoAsk(r){var A=aoFor(r);if(!A||AOB[r.id]!=="ask")return "";var sol=r.chain==="solana",cid="'"+r.id+"'";if(sol&&!aoBuy(r)){var a=aoSellSol(r),shr=r.sell_percent!=null&&(S.rules||[]).some(function(x){return x.id!==r.id&&x.chain==="solana"&&!aoBuy(x)&&x.sell_percent!=null&&A.rules.indexOf(x.id)>=0}),held=A.held&&A.held.wsol_balance||0;if(shr&&held>0)a=Math.max(a,held);return '<div class="aoask"><div class="sm">'+(shr?'Uses the <b>'+fmtAmt(a)+' SOL</b> already set aside':'Set aside <b>'+(a>0?fmtAmt(a):"0")+' SOL</b> for this sell')+'</div><div class="sm mut">It stays in your wallet as wrapped SOL, and TOLLkit can sell only that much. Turning it off unwraps it.</div><div class="tc-crow"><button class="b"'+(a>0?"":" disabled")+' onclick="aoSend('+cid+',true)">Turn on</button><button class="b g" onclick="delete AOB['+cid+'];render()">Cancel</button></div>'+(a>0?"":'<div class="sm warn">No SOL to set aside (0.02 SOL stays for fees).</div>')+'</div>'}var cap=sol?A.usd_cap:A.budget_usd;return '<div class="aoask"><div class="sm">'+(sol?"Most USDC TOLLkit can spend on Solana":"Most it can spend while the app is closed")+'</div><div class="tc-crow"><input id="aobud" type="number" min="1" step="1" value="'+(cap||Math.max(50,Math.ceil((r.amount_usd||10)*7)))+'"><button class="b" onclick="aoBudget('+cid+')">Turn on</button><button class="b g" onclick="delete AOB['+cid+'];render()">Cancel</button></div><div class="sm mut">'+(sol?"Your wallet signs this allowance once. It refills when you open TOLLkit, and you can revoke it in Settings.":"Your coins stay in your wallet. Trades come straight back to it.")+'</div></div>'}
