// ── Drag to set: the template's percentages as lines on the token's chart, both ways in sync with the boxes.
function tplVal(t,k){var f=t.fields.filter(function(x){return x.key===k})[0];var v=BOT.params[k];return Number(v!==undefined&&v!==""?v:f?f.default:0)}
function formLevels(t,P){var v=function(k){return tplVal(t,k)},L=[];
if(t.id==="dip"){var b=P*(1-v("drop_pct")/100);L.push({price:b,kind:"buy",label:"Buy",key:"drop_pct"},{price:b*(1+v("profit_pct")/100),kind:"sell",label:"Sell",key:"profit_pct"})}
else if(t.id==="protect")L.push({price:P*(1-v("stop_pct")/100),kind:"stop",label:"Stop",key:"stop_pct"},{price:P*(1+v("profit_pct")/100),kind:"sell",label:"Take profit",key:"profit_pct"});
else if(t.id==="trail")L.push({price:P*(1-v("trail_pct")/100),kind:"stop",label:"Sells if it falls to",key:"trail_pct"});
else if(t.id==="ladder")L.push({price:P*(1+v("step1")/100),kind:"sell",label:"Sell ¼",key:"step1"},{price:P*(1+v("step2")/100),kind:"sell",label:"Sell ¼",key:"step2"},{price:P*(1+v("step3")/100),kind:"sell",label:"Sell rest",key:"step3"});
else if(t.id==="smart_dca"){for(var k=1;k<=Math.min(10,Math.round(v("safety")));k++)L.push({price:P*Math.pow(1-v("step_pct")/100,k),kind:"buy",label:"Extra buy "+k,key:k===1?"step_pct":undefined});L.push({price:P*(1+v("profit_pct")/100),kind:"sell",label:"Sells all",key:"profit_pct"})}
else if(t.id==="rebalance"){var tg=v("target_pct")/100,bd=v("band_pct")/100,at=function(sh){return P*sh*(1-tg)/((1-sh)*tg)};if(tg+bd<1)L.push({price:at(tg+bd),kind:"sell",label:"Sells some above"});if(tg-bd>0)L.push({price:at(tg-bd),kind:"buy",label:"Buys some below"})}
else if(t.id==="infinity_grid")L.push({price:P*(1+v("step_pct")/100),kind:"sell",label:"Sells the extra"},{price:P*(1-v("step_pct")/100),kind:"buy",label:"Buys back",key:"step_pct"},{price:P*(1-v("floor_pct")/100),kind:"stop",label:"No buys below",key:"floor_pct"});
else if(t.id==="grid"){var r=v("range_pct")/100,n=Math.max(3,Math.round(v("levels"))),lo=P*(1-r),hi=P*(1+r);for(var i=0;i<n;i++){var p=lo+(hi-lo)*i/(n-1);L.push({price:p,kind:"grid",label:i===0?"Grid bottom":i===n-1?"Grid top":"Grid level",key:i===0||i===n-1?"range_pct":undefined})}}
return L}
// The percentage a dragged line means, from its price.
function pctFor(t,key,price,P){var v=function(k){return tplVal(t,k)};
if(key==="drop_pct"||key==="stop_pct"||key==="trail_pct"||key==="step_pct"||key==="floor_pct")return (1-price/P)*100;
if(key==="profit_pct")return t.id==="dip"?(price/(P*(1-v("drop_pct")/100))-1)*100:(price/P-1)*100;
if(key==="range_pct")return Math.abs(price/P-1)*100;
return (price/P-1)*100}
