var SB_PRESETS={careful:{per_trade_usd:10,max_token_pct:20,daily_loss_pct:3,weekly_loss_pct:10,paper_days:14,paper_trades:30},balanced:{per_trade_usd:20,max_token_pct:25,daily_loss_pct:5,weekly_loss_pct:15,paper_days:7,paper_trades:20},bold:{per_trade_usd:40,max_token_pct:35,daily_loss_pct:8,weekly_loss_pct:20,paper_days:5,paper_trades:15}};
