H.forEach(function(h){if(h.chain!==c||!h.symbol||/^(USDC|USDT|DAI|ETH|WETH|SOL|WSOL|POL|WPOL)$/i.test(h.symbol))return;if(h.trust==="unlisted"&&!h.watched)return;if(!o.some(function(x){return sbSame(x.t,h.address)||sbSame(x.s,h.symbol)}))o.push({t:h.address,s:h.symbol,l:h.logo||null})});
